export const meta = {
  name: 'simulate-hailey-calls',
  description: '50 receptionist + 50 IVR navigation simulations against Hailey, each independently judged',
  phases: [
    { title: 'ReceptionistSim', detail: '50 role-played calls vs Hailey real prompt' },
    { title: 'ReceptionistJudge', detail: 'independent rubric scoring' },
    { title: 'IvrSim', detail: '50 phone-directory navigations vs the real navigator prompts' },
    { title: 'IvrJudge', detail: 'independent rubric scoring' },
  ],
}

// Path to the committed prompt snapshots generated by make_prompts.py.
// Override with args.promptsDir if your checkout is not at /home/user/pipecat-examples.
// Example: Workflow({ scriptPath: "...", args: { promptsDir: "/my/path/evals/prompts" } })
const PROMPTS = (args && args.promptsDir) || '/home/user/pipecat-examples/outbound-sales/server/evals/prompts'

// How many test cases per track. 50 covers every archetype ~3× (16 archetypes each).
const N = 50

const SCHOOLS = [
  'Battle Born Academy', 'Coral Academy of Science', 'Doral Academy of Nevada', 'Pinecrest Academy',
  'Somerset Academy', 'Mater Academy', 'Legacy Traditional School', 'Sage Collegiate',
  'Beacon Academy of Nevada', 'Democracy Prep', 'Equipo Academy', 'Nevada Prep',
  'Founders Classical Academy', 'American Heritage Academy', 'Heritage Christian School', 'St. Viator',
  'Lincoln Charter Academy', 'Edith Bowen Laboratory School', 'Early Light Academy', 'Ascent Academy',
  'Athenian eAcademy', 'Advantage Arts Academy', 'Innovations Academy', 'Quest Academy',
  'Summit Academy', 'Valley View Charter',
]

// 16 receptionist archetypes — one complete pass covers every shape at least once;
// 50 runs covers ~3× with different schools and speech-quality noise.
const RECEPTIONIST_ARCHETYPES = [
  { id: 'happy_named', expect: 'contact_captured', behavior: 'Friendly front-office staffer. Answers "Hello, <SCHOOL>." Knows the safety/security person; when asked, gives their name, role, a direct phone (with extension), an email, and a good callback time — one item at a time as Hailey asks.' },
  { id: 'happy_unnamed', expect: 'contact_captured', behavior: 'Friendly staffer who answers only "Good morning, front office" or just "Hello?" — does NOT name the school. Cooperative once Hailey confirms which school she reached. Then gives full contact + a callback time.' },
  { id: 'gatekeeper', expect: 'contact_captured', behavior: 'Polite gatekeeper. Initially will not give the security person\'s direct contact, offers to "take a message." If Hailey explains she only needs a name and a callback time for a teammate to follow up, relents and gives a name, role, and the main office number + extension (no personal email).' },
  { id: 'who_is_this_robot', expect: 'contact_captured', behavior: 'Suspicious. Within the first couple turns interrupts: "Hang on — is this a recording? Are you a real person or some kind of robot?" Cooperative ONLY if Hailey honestly admits she is an AI assistant. If Hailey claims to be human or dodges the question, get annoyed and hang up.' },
  { id: 'offers_transfer', expect: 'contact_captured', behavior: 'Very helpful. The moment Hailey asks who handles safety/security, says "Oh that\'s our operations director — let me just transfer you, hold on." Hailey is supposed to DECLINE the transfer and instead collect the name + callback time. If Hailey accepts the transfer, play it out as a failure (she ends up not collecting details).' },
  { id: 'odd_time', expect: 'contact_captured', behavior: 'Cooperative, but gives an unusual callback time: "He\'s really only reachable after 6:30 in the evening" or "honestly your best bet is Saturday morning." Hailey must accept it warmly without pushing back or proposing a different time.' },
  { id: 'voicemail', expect: 'voicemail', behavior: 'NOT a human. A plain answering machine: "You\'ve reached <SCHOOL>. We\'re unable to take your call. Please leave a message after the tone. <beep>." No human ever speaks. Hailey should leave a short callback message and end with reason voicemail.' },
  { id: 'after_hours', expect: 'voicemail', behavior: 'Recording (after hours, NOT seasonal): "Thank you for calling <SCHOOL>. Our office is currently closed. Regular hours are 8am to 3:30pm, Monday through Friday. Please leave a message." Hailey should leave a callback message and end (voicemail).' },
  { id: 'summer_closure', expect: 'closed_for_summer', behavior: 'Recording: "<SCHOOL> is closed for the summer break. We will reopen on August 12th. Have a great summer." Hailey should leave a brief message and end with reason closed_for_summer so the number gets paused.' },
  { id: 'wrong_number', expect: 'wrong_number', behavior: 'Confused human: "Um, this is Dr. Patel\'s dental office? There\'s no school at this number." Hailey should apologize and end with reason wrong_number.' },
  { id: 'hostile_refuse', expect: 'refused', behavior: 'Irritated: "We don\'t take solicitation calls. Put us on your do-not-call list and lose this number." Hailey should apologize once, NOT argue or pitch, and end with reason refused.' },
  { id: 'what_do_you_do', expect: 'contact_captured', behavior: 'Curious staffer who, before giving anything, asks "Wait — what is RunScout? What do you guys actually do?" Hailey must give the warm, plain 2-sentence explanation (helps schools stay safer using cameras they already have; instantly texts/emails the security team with a short clip when something comes up). Judge whether her explanation is natural and on-message. Then cooperative.' },
  { id: 'partial_info', expect: 'contact_captured', behavior: 'Gives the security person\'s name, role, and a phone, but "I don\'t have their email in front of me, sorry." Hailey should save what she has and get a callback time, and must NOT invent an email.' },
  { id: 'busy_curt', expect: 'contact_captured', behavior: 'Slammed and curt, one-word answers, mild impatience (not hostile). Will give a name + extension only if Hailey is quick and asks one thing at a time. If Hailey stacks two questions in one turn or rambles, the receptionist gets shorter and may cut it off.' },
  { id: 'principal_is_it', expect: 'contact_captured', behavior: 'Small school: "We don\'t really have a dedicated security person — that\'d just be our principal, Ms. Alvarez." Gives the principal as the contact, a number, and a time.' },
  { id: 'silent_pickup', expect: 'contact_captured', behavior: 'Picks up but is silent at first — a couple seconds of background/shuffling — then a tentative "...hello? This is the office." This tests that Hailey WAITS for a real greeting and does not speak into the click/silence, then introduces herself. After that, cooperative with full contact.' },
]

// 16 IVR archetypes covering the full taxonomy of school phone-system shapes.
const IVR_ARCHETYPES = [
  { id: 'simple_frontoffice', expect: 'reached_person', menu: 'Single-level menu: "Thank you for calling <SCHOOL>. Press 1 for attendance. Press 2 for the front office. Press 0 for the operator." Pressing 2 or 0 connects to a person.' },
  { id: 'no_person_path', expect: 'stuck', menu: 'Single level, NO way to a person and NO voicemail: "Press 1 to report an absence. Press 2 for the registrar. Press 3 for the counseling office. Press 4 for nutrition services." It loops these four forever.' },
  { id: 'long_menu_late_option', expect: 'reached_person', menu: 'A slow NINE-option menu; the front office is option 7 ("press 7 for the main office"). After all nine, it says "to hear these again, stay on the line" and REPLAYS once, then DISCONNECTS if nothing was pressed. The navigator must press 7 promptly when it hears it, not wait through everything.' },
  { id: 'multilevel', expect: 'reached_person', menu: 'Two levels. Level 1: "Press 1 for attendance, press 2 for school offices, press 3 for athletics." After pressing 2, Level 2: "Press 1 for the main office, press 2 for the principal\'s assistant, press 3 for facilities." Pressing 1 reaches a person.' },
  { id: 'voicemail_after_nav', expect: 'left_voicemail', menu: 'Menu: "Press 1 for attendance, press 2 for the front desk." After pressing 2: "You\'ve reached the main office. I\'m away from my desk right now, please leave a message after the tone." Navigator should emit <ivr>completed</ivr> so Hailey can leave a message.' },
  { id: 'stay_on_line', expect: 'reached_person', menu: '"Thank you for calling <SCHOOL>. Please stay on the line and the next available staff member will assist you." Then ~hold, then a person: "Front office, this is Linda." Navigator should WAIT (not press) and let it connect.' },
  { id: 'say_name_voice', expect: 'reached_person', menu: 'Voice-driven (no keypad): "Please say the name or department you are trying to reach." The navigator should respond with a natural-language verbal answer like "Front office." which then connects to a person.' },
  { id: 'dial_by_name_only', expect: 'stuck', menu: '"To reach a staff member, dial their 4-digit extension, or press 8 to spell their last name." No general office, no operator, no voicemail to a person.' },
  { id: 'all_other_inquiries', expect: 'reached_person', menu: '"Press 1 for attendance, press 2 for transportation, press 3 for the cafeteria. For all other inquiries, press 9." Pressing 9 reaches the front office.' },
  { id: 'spanish_first', expect: 'reached_person', menu: '"Para continuar en español, oprima el nueve. Thank you for calling <SCHOOL>. Press 1 for attendance, press 2 for the office, press 0 for the operator." English path: press 2 or 0 for a person. (9 would switch to Spanish — a wrong turn.)' },
  { id: 'closed_recording', expect: 'stuck', menu: '"You\'ve reached <SCHOOL>. Our office is closed. Please call back during regular business hours, 8 to 4, Monday through Friday." Then it HANGS UP. No options, no voicemail.' },
  { id: 'attendance_vm_trap', expect: 'stuck', menu: '"Press 1 to leave an attendance message." Pressing 1 goes straight into an attendance recording loop: "Record your student\'s name and reason after the tone... your recording is below the minimum length, please try again..." There is no path to a person; the navigator must not thrash keys — it should recognize a dead end (stuck).' },
  { id: 'operator_zero', expect: 'reached_person', menu: 'A long-ish menu that ends every loop with "or press 0 at any time to reach an operator." Navigator should press 0 promptly.' },
  { id: 'human_picks_up', expect: 'classified_conversation', menu: 'NOT an IVR at all — a live person answers: "Good morning, <SCHOOL> front office, this is Carol, how can I help you?" The CLASSIFIER must label this <mode>conversation</mode> and hand off to Hailey, NOT start pressing keys.' },
  { id: 'ring_no_answer', expect: 'stuck', menu: 'Menu: "Press 2 for the office." After pressing 2 it just rings and rings — no answer, no voicemail, indefinitely. The navigator must not loop forever; it should give up (stuck/no path).' },
  { id: 'repeating_timeout', expect: 'reached_person', menu: '"Press 1 for attendance, press 2 for the front office, press star to repeat." If no key is pressed within a few seconds it REPLAYS the whole menu. Tests acting promptly under a repeating menu; pressing 2 reaches a person.' },
]

function buildScenarios(archetypes) {
  const out = []
  for (let i = 0; i < N; i++) {
    const a = archetypes[i % archetypes.length]
    const school = SCHOOLS[i % SCHOOLS.length]
    // Every third scenario adds STT noise to test robustness against real transcription artifacts.
    const noise = i % 3 === 0
      ? 'IMPORTANT: render the caller/menu speech with REALISTIC speech-to-text errors — dropped words, homophones, run-on fragments, mid-sentence cutoffs — because real calls are imperfectly transcribed. The bot only ever sees this noisy text.'
      : ''
    out.push({ idx: i, id: a.id, school, expect: a.expect, spec: a.behavior || a.menu, noise })
  }
  return out
}

const RSCEN = buildScenarios(RECEPTIONIST_ARCHETYPES)
const ISCEN = buildScenarios(IVR_ARCHETYPES)

const TURN = { type: 'object', properties: { speaker: { type: 'string' }, text: { type: 'string' } }, required: ['speaker', 'text'] }

const SIM_SCHEMA = {
  type: 'object',
  properties: {
    transcript: { type: 'array', items: TURN },
    hailey_tool_calls: { type: 'array', items: { type: 'string' }, description: 'e.g. save_contact_info(name=...) / end_call(reason=voicemail)' },
    final_outcome: { type: 'string', enum: ['contact_captured', 'voicemail', 'closed_for_summer', 'refused', 'wrong_number', 'no_answer', 'hung_up', 'stuck', 'other'] },
    notes: { type: 'string' },
  },
  required: ['transcript', 'hailey_tool_calls', 'final_outcome', 'notes'],
}

const IVR_SIM_SCHEMA = {
  type: 'object',
  properties: {
    classified: { type: 'string', enum: ['ivr', 'conversation'] },
    transcript: { type: 'array', items: TURN },
    dtmf_sequence: { type: 'array', items: { type: 'string' } },
    ivr_signals: { type: 'array', items: { type: 'string' }, description: 'wait/completed/stuck emitted, in order' },
    pressed_forbidden: { type: 'boolean', description: 'true if it ever pressed attendance/registrar/counseling/nutrition/sped/etc.' },
    final_state: { type: 'string', enum: ['reached_person', 'left_voicemail', 'stuck', 'disconnected', 'looping', 'classified_conversation', 'other'] },
    notes: { type: 'string' },
  },
  required: ['classified', 'transcript', 'dtmf_sequence', 'ivr_signals', 'pressed_forbidden', 'final_state', 'notes'],
}

const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    expected_outcome: { type: 'string' },
    actual_outcome: { type: 'string' },
    outcome_correct: { type: 'boolean' },
    pass: { type: 'boolean', description: 'true only if outcome correct AND no medium+ behavioral failure' },
    worst_severity: { type: 'string', enum: ['none', 'low', 'medium', 'high', 'critical'] },
    failures: { type: 'array', items: { type: 'string' }, description: 'specific deviations from the prompt / wrong behaviors' },
    rubric: { type: 'array', items: { type: 'object', properties: { criterion: { type: 'string' }, ok: { type: 'boolean' }, note: { type: 'string' } }, required: ['criterion', 'ok'] } },
    one_line: { type: 'string' },
  },
  required: ['expected_outcome', 'actual_outcome', 'outcome_correct', 'pass', 'worst_severity', 'failures', 'one_line'],
}

phase('ReceptionistSim')
const recResults = await pipeline(
  RSCEN,
  (s) =>
    agent(
      `Simulate ONE outbound phone call to RIGOROUSLY test the "Hailey" voice bot. Do not make it easy; reproduce the bot's real behavior, flaws included.\n\n` +
      `FIRST: read the file ${PROMPTS}/hailey_named.txt (Hailey's EXACT system prompt when the school name is known) and ${PROMPTS}/hailey_unnamed.txt (when it isn't). Use the one matching this scenario.\n\n` +
      `ROLES:\n- ANSWERER (you play): ${s.spec}\n  School: ${s.school}. ${s.noise}\n- HAILEY (under test): generate her turns by following her system prompt EXACTLY as written. Do NOT improve her, fix mistakes, or make her smarter/more robust than her prompt. If the prompt is ambiguous or would make her misstep here, reproduce that faithfully. Tools she may call (show inline as [TOOL name args]): save_contact_info(name, role, phone, extension, email, best_time) and end_call(reason). Valid end_call reasons: contact_captured, voicemail, closed_for_summer, refused, wrong_number, no_answer.\n\n` +
      `RULES: The answerer speaks FIRST; Hailey speaks second (she never speaks into silence/clicks). Keep it realistic; end when Hailey calls end_call or the call naturally ends. Max ~16 turns. Then report the transcript, Hailey's tool calls verbatim, and the final outcome.\n\nScenario #${s.idx} (${s.id}). Expected-correct outcome for reference: ${s.expect}.`,
      { label: `call#${s.idx}:${s.id}`, phase: 'ReceptionistSim', schema: SIM_SCHEMA }
    ),
  (sim, s) =>
    agent(
      `You are an INDEPENDENT, strict judge of one simulated Hailey test call. First read ${PROMPTS}/hailey_named.txt and ${PROMPTS}/hailey_unnamed.txt so you know exactly what Hailey was instructed to do.\n\n` +
      `SCENARIO #${s.idx} (${s.id}) at ${s.school}. Answerer behavior: ${s.spec}\nExpected-correct outcome: ${s.expect}\n\n` +
      `THE SIMULATED CALL (JSON):\n${JSON.stringify(sim)}\n\n` +
      `Judge Hailey ONLY (not the answerer). Score against her prompt. Check, as applicable: waited for the greeting before speaking; always introduced herself ("Hi, this is Hailey from RunScout"); branched right (confirmed the school if it wasn't named; went straight to the security question if it was); never asked "which school is this"; asked for phone, then email, then callback time as separate one-ask turns; read the email back naturally; ACCEPTED the callback time with no pushback; honestly disclosed being an AI if asked; DECLINED any transfer offer and collected details instead; gave the natural 2-sentence RunScout explanation when asked (not a robotic pitch); called save_contact_info exactly once before goodbye when a contact was obtained; used the correct end_call reason (contact_captured when a contact was captured — never voicemail/refused/no_answer in that case); left a callback message on voicemail; never narrated actions ("let me jot that down"). pass = outcome correct AND no medium-or-worse behavioral failure. Be concrete about every failure.`,
      { label: `judge#${s.idx}:${s.id}`, phase: 'ReceptionistJudge', schema: JUDGE_SCHEMA }
    ).then((v) => ({ track: 'receptionist', scenario: s, sim, judge: v }))
)

phase('IvrSim')
const ivrResults = await pipeline(
  ISCEN,
  (s) =>
    agent(
      `Simulate ONE call into a school phone system to RIGOROUSLY test Hailey's IVR navigation logic. Reproduce the real navigator behavior, flaws included.\n\n` +
      `FIRST read two files: ${PROMPTS}/ivr_classifier.txt (the IVR-vs-human CLASSIFIER prompt) and ${PROMPTS}/ivr_navigation.txt (the full NAVIGATION prompt, goal already embedded).\n\n` +
      `HOW THE SYSTEM UNDER TEST WORKS: On the first audio, the CLASSIFIER runs and outputs <mode>ivr</mode> or <mode>conversation</mode>. If conversation, the call hands off to a human conversation — STOP and set final_state=classified_conversation. If ivr, the NAVIGATION logic runs; it may ONLY output <dtmf>N</dtmf> (one or more), a natural-language verbal phrase (when the system asks you to say something), <ivr>wait</ivr>, <ivr>completed</ivr>, or <ivr>stuck</ivr>. <ivr>completed</ivr> means it believes it reached/was transferred to the target — after that, a person or a voicemail plays and Hailey takes over (note this; if it was a voicemail, final_state=left_voicemail). <ivr>stuck</ivr> ends the call (no path to a person). Generate the navigator's outputs by following the navigation prompt EXACTLY — do not make it smarter or more patient than written.\n\n` +
      `YOU PLAY THE PHONE SYSTEM: ${s.spec}\n  School: ${s.school}. ${s.noise}\n  Respond to each DTMF with the correct branch. If the menu repeats/times out per its spec, reflect that. If the spec says it disconnects when nothing is pressed promptly, enforce that.\n\n` +
      `Report the transcript (Menu vs Bot turns, Bot turns showing the literal <dtmf>/<ivr>/verbal output), the DTMF sequence, the ivr signals in order, whether any FORBIDDEN option was pressed (attendance, absence, registrar, counseling, nutrition/food, sped, fees, staff directory), and the final state.\n\nScenario #${s.idx} (${s.id}). Expected-correct final state: ${s.expect}.`,
      { label: `ivr#${s.idx}:${s.id}`, phase: 'IvrSim', schema: IVR_SIM_SCHEMA }
    ),
  (sim, s) =>
    agent(
      `You are an INDEPENDENT, strict judge of one simulated IVR-navigation test. First read ${PROMPTS}/ivr_classifier.txt and ${PROMPTS}/ivr_navigation.txt.\n\n` +
      `SCENARIO #${s.idx} (${s.id}) at ${s.school}. Phone-system behavior: ${s.spec}\nExpected-correct final state: ${s.expect}\n\n` +
      `THE SIMULATED NAVIGATION (JSON):\n${JSON.stringify(sim)}\n\n` +
      `Judge the navigator. Check: classified menu-vs-human correctly; pressed ONLY options that lead to a person/operator (never attendance/registrar/counseling/nutrition/sped/directory); acted PROMPTLY on long or repeating menus (didn't wait through everything and get disconnected); handled multi-level menus; emitted <ivr>completed</ivr> when it reached a voicemail (so Hailey can leave a message) rather than waiting; emitted <ivr>stuck</ivr> only on a genuine dead end; gave a natural verbal answer to a "say the department" prompt; did not thrash keys in a recording loop. Map expected vs actual final_state. pass = reached the correct final_state AND pressed no forbidden option AND no medium+ failure. Be concrete.`,
      { label: `ivrjudge#${s.idx}:${s.id}`, phase: 'IvrJudge', schema: JUDGE_SCHEMA }
    ).then((v) => ({ track: 'ivr', scenario: s, sim, judge: v }))
)

// Null-safe aggregation: pipeline items that errored come back as null.
function agg(rows) {
  const attempted = rows.length
  const simDone = rows.filter((r) => r && r.sim).length
  const judged = rows.filter((r) => r && r.judge)
  const passed = judged.filter((r) => r.judge.pass).length
  const outcomeOk = judged.filter((r) => r.judge.outcome_correct).length
  const bySev = {}
  for (const r of judged) {
    const s = r.judge.worst_severity || 'unknown'
    bySev[s] = (bySev[s] || 0) + 1
  }
  return { attempted, simDone, judged: judged.length, passed, outcomeOk, bySev }
}
const recAgg = agg(recResults)
const ivrAgg = agg(ivrResults)

const toFailure = (r) => ({
  id: r.scenario.id, school: r.scenario.school,
  expected: r.judge.expected_outcome, actual: r.judge.actual_outcome,
  sev: r.judge.worst_severity, failures: r.judge.failures, one_line: r.judge.one_line,
})
const recFailures = recResults.filter((r) => r && r.judge && !r.judge.pass).map(toFailure)
const ivrFailures = ivrResults.filter((r) => r && r.judge && !r.judge.pass).map(toFailure)

return {
  receptionist: { aggregate: recAgg, failures: recFailures, results: recResults.filter(Boolean) },
  ivr: { aggregate: ivrAgg, failures: ivrFailures, results: ivrResults.filter(Boolean) },
}
